package org.millenaire.common.entity;import org.millenaire.common.utilities.Point;public class MillVillager{public net.minecraft.world.level.Level level;public Point dest;public boolean reject;public int swings;public Point getGoalDestPoint(){return dest;}public boolean setBlockstate(Point p,net.minecraft.world.level.block.state.BlockState s){if(reject)return false;Point.cells.put(p.pos,s);return true;}public void swing(net.minecraft.world.InteractionHand h){swings++;}}